[ -z "$(bash src/remind.sh 2026/01/01 2>/dev/null)" ] || { echo "remind: a malformed date should print nothing to stdout"; fail=1; }
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-02\t10:00\t11:00\tx\n' > "$t"
[ "$(BOOKINGS=$t bash src/remind.sh 2026-01-02)" = 'reminder to x: aoi 2026-01-02 10:00-11:00' ] || { echo "remind: a well-formed date should remind"; fail=1; }
rm -f "$t"
exit $fail

