BOOKINGS=$t bash src/list.sh 2026-01-32 >/dev/null 2>&1; [ $? = 2 ] || { echo "day 32 should exit 2"; fail=1; }
BOOKINGS=$t bash src/list.sh 2026-01-02 >/dev/null 2>&1; [ $? = 0 ] || { echo "a well-formed date should pass"; fail=1; }
