#!/bin/bash
# Date helpers. Dates are YYYY-MM-DD; month 01-12, day 01-31 (cli-conventions.md).
# check_date DATE: succeeds for a valid date; otherwise prints "bad date" to stderr and fails (callers exit 2).
check_date() {
  if ! [[ "$1" =~ ^[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$ ]]; then
    echo "bad date: $1 (expected YYYY-MM-DD)" >&2
    return 1
  fi
}

#!/bin/bash
# list.sh [DATE]: bookings, one per line "DATE START-END ROOM WHO", sorted. src/remind.sh reads this.
set -u
. "$(dirname "$0")/lib/date.sh"
BOOKINGS=${BOOKINGS:-data/bookings.tsv}
if [ -n "${1:-}" ]; then check_date "$1" || exit 2; fi
[ -r "$BOOKINGS" ] || { echo "bookings file not found: $BOOKINGS" >&2; exit 2; }
grep -v '^#' "$BOOKINGS" | awk -F'\t' -v d="${1:-}" 'NF && (d == "" || $2 == d) { printf "%s %s-%s %s %s\n", $2, $3, $4, $1, $5 }' | sort

#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-02\t10:00\t11:00\tx\n' > "$t"
for s in src/list.sh src/remind.sh; do
  for d in 2026/01/01 2026-13-01 2026-01-32 2026-00-10; do
    BOOKINGS=$t bash "$s" "$d" >/dev/null 2>&1; [ $? = 2 ] || { echo "$s $d should exit 2"; fail=1; }
    [ "$(BOOKINGS=$t bash "$s" "$d" 2>&1 >/dev/null)" = "bad date: $d (expected YYYY-MM-DD)" ] || { echo "$s $d: bad date message"; fail=1; }
    [ -z "$(BOOKINGS=$t bash "$s" "$d" 2>/dev/null)" ] || { echo "$s $d: stdout should be empty"; fail=1; }
  done
  BOOKINGS=$t bash "$s" 2026-01-02 >/dev/null 2>&1; [ $? = 0 ] || { echo "$s: a valid date should exit 0"; fail=1; }
done
[ "$(BOOKINGS=$t bash src/remind.sh 2026-01-02)" = 'reminder to x: aoi 2026-01-02 10:00-11:00' ] || { echo "remind by date"; fail=1; }
rm -f "$t"; exit $fail

